    private(set) var searchTranscriptsCallCount = 0
    private(set) var getRecordingCallCount = 0
    private let summaries: [RecordingSummary]
    private let storedRecording: StoredRecording?
    private let recordingNotFoundError: StorageError?

    init(
        summaries: [RecordingSummary] = [],
        storedRecording: StoredRecording? = nil,
